'use strict'

import clock from './clock'

const BLOCKING_ACTION = true
const ENABLED = true
const STORAGE_KEY_BINDINGS = 'loz-key-bindings'
// How long a blocking action (item button) stays active after a press
const BLOCKING_ACTION_DURATION = 250

class Key {
  constructor (key, action, blockingAction, enabled) {
    this.key = key
    this.action = action
    this.blockingAction = blockingAction
    this.enabled = enabled

    this.pressed = false
    this.used = false
  }

  use () {
    this.used = true

    return this.action
  }

  disable () {
    this.enabled = false
  }

  enable () {
    this.enabled = true
  }

  unuse () {
    this.used = false

    return this.action
  }

  press () {
    this.pressed = true
  }

  unpress () {
    this.pressed = false
  }

  static get BLOCKING_ACTION () {
    return BLOCKING_ACTION
  }

  static get ENABLED () {
    return ENABLED
  }
}

export default {

  ACTION_LINK_MOVE_WEST: 'link_move_west',
  ACTION_LINK_MOVE_NORTH: 'link_move_north',
  ACTION_LINK_MOVE_EAST: 'link_move_east',
  ACTION_LINK_MOVE_SOUTH: 'link_move_south',
  ACTION_LINK_USE_ITEM_A: 'link_use_item_a',
  ACTION_LINK_USE_ITEM_B: 'link_use_item_b',
  ACTION_MENU_CLOSE: 'menu_close',
  ACTION_MENU_MOVE_LEFT: 'menu_move_left',
  ACTION_MENU_MOVE_TOP: 'menu_move_top',
  ACTION_MENU_MOVE_RIGHT: 'menu_move_right',
  ACTION_MENU_MOVE_BOTTOM: 'menu_move_bottom',
  ACTION_MENU_OPEN: 'menu_open',

  MAPPING_MAIN: 'mapping_main',
  MAPPING_MENU: 'mapping_menu',

  mappings: {},

  currentMappingName: undefined,

  actionKeys: [],

  bindings: {},

  // Default key of each action, as KeyboardEvent.code values (physical position, independent of the
  // keyboard layout). A is the sword and B the secondary item, as on the NES controller
  get defaultBindings () {
    return {
      [this.ACTION_LINK_MOVE_WEST]: 'ArrowLeft',
      [this.ACTION_LINK_MOVE_NORTH]: 'ArrowUp',
      [this.ACTION_LINK_MOVE_EAST]: 'ArrowRight',
      [this.ACTION_LINK_MOVE_SOUTH]: 'ArrowDown',
      [this.ACTION_LINK_USE_ITEM_A]: 'KeyA',
      [this.ACTION_LINK_USE_ITEM_B]: 'KeyB'
    }
  },

  // Keys chosen by the player (see rebind), or the defaults. A saved set where two actions
  // share a key is ignored
  loadBindings: function () {
    const bindings = this.defaultBindings
    let saved
    try {
      saved = JSON.parse(globalThis.localStorage?.getItem(STORAGE_KEY_BINDINGS) ?? 'null')
    } catch (e) {
      saved = undefined
    }
    if (saved && typeof saved === 'object') {
      for (const action of Object.keys(bindings)) {
        if (typeof saved[action] === 'string') {
          bindings[action] = saved[action]
        }
      }
    }
    const codes = Object.values(bindings)
    this.bindings = new Set(codes).size === codes.length ? bindings : this.defaultBindings
  },

  saveBindings: function () {
    try {
      globalThis.localStorage?.setItem(STORAGE_KEY_BINDINGS, JSON.stringify(this.bindings))
    } catch (e) {
      // Storage unavailable (private browsing, blocked site data): the keys only last for the session
    }
  },

  getBinding: function (action) {
    if (Object.keys(this.bindings).length === 0) {
      this.loadBindings()
    }

    return this.bindings[action]
  },

  // Binds an action to another key. If another action used that key, the two are swapped
  rebind: function (action, code) {
    const previousCode = this.bindings[action]
    if (previousCode === undefined || previousCode === code) {
      return
    }
    const otherAction = Object.keys(this.bindings).find(other => this.bindings[other] === code)
    if (otherAction) {
      this.bindings[otherAction] = previousCode
    }
    this.bindings[action] = code
    this.saveBindings()
    this.remap()
  },

  resetBindings: function () {
    this.bindings = this.defaultBindings
    this.saveBindings()
    this.remap()
  },

  // Moves the existing keys to their new codes, keeping their state (item buttons enabled or not)
  remap: function () {
    const keys = Object.values(this.mappings)
    this.mappings = {}
    for (const key of keys) {
      key.key = this.bindings[key.action]
      key.unuse()
      key.unpress()
      this.mappings[key.key] = key
    }
    this.clear()
  },

  setMapping: function () {
    if (Object.keys(this.bindings).length === 0) {
      this.loadBindings()
    }
    const itemActions = [this.ACTION_LINK_USE_ITEM_A, this.ACTION_LINK_USE_ITEM_B]
    this.mappings = {}
    for (const [action, code] of Object.entries(this.bindings)) {
      // Item buttons stay disabled until an item is equipped
      const isItemAction = itemActions.includes(action)
      this.mappings[code] = new Key(code, action, isItemAction ? Key.BLOCKING_ACTION : !Key.BLOCKING_ACTION, isItemAction ? !Key.ENABLED : Key.ENABLED)
    }
  },

  getCurrentDrawingAction: function () {
    for (let i = 0; i < this.actionKeys.length; i++) {
      if (this.actionKeys[i].blockingAction) {
        return this.actionKeys[i].use()
      }
    }

    return this.actionKeys[0]?.use()
  },

  getCurrentAction: function () {
    for (let i = 0; i < this.actionKeys.length; i++) {
      if (this.actionKeys[i].blockingAction && !this.actionKeys[i].used) {
        return this.actionKeys[i].use()
      }
    }

    return this.actionKeys[0] && !this.actionKeys[0].blockingAction ? this.actionKeys[0].use() : undefined
  },

  clear: function () {
    this.actionKeys = []
  },

  getKey: function (code) {
    return this.mappings[code]
  },

  addActionKey: function (key) {
    this.actionKeys.unshift(key)
  },

  removeActionKey: function (key) {
    const index = this.actionKeys.indexOf(key)
    if (index !== -1) {
      this.actionKeys.splice(index, 1)
    }
  },

  triggerBlockingAction (key) {
    if (key.blockingAction) {
      key.disable()
      const inputManager = this
      clock.delay(() => {
        inputManager.removeActionKey(key)
        key.enable()
      }, BLOCKING_ACTION_DURATION)
    }
  },

  handleKeyDown: function (code) {
    const key = this.getKey(code)
    if (!key || !key.enabled) {
      return
    }

    if (key && !key.pressed) {
      this.removeActionKey(key)
      this.addActionKey(key)
      this.triggerBlockingAction(key)
      key.press()
    }
  },

  handleKeyUp: function (code) {
    const key = this.getKey(code)
    if (!key) {
      return
    }
    this.removeActionKey(key)
    key.unuse()
    key.unpress()
  },

  enable (action) {
    for (const key in this.mappings) {
      if (this.mappings[key].action === action) {
        this.mappings[key].enable()
      }
    }
  },

  startDetection: function () {
    this.stopDetection()
    this.keyDownListener = (e) => this.handleKeyDown(e.code)
    this.keyUpListener = (e) => this.handleKeyUp(e.code)
    document.addEventListener('keydown', this.keyDownListener)
    document.addEventListener('keyup', this.keyUpListener)
  },

  stopDetection: function () {
    if (this.keyDownListener) {
      document.removeEventListener('keydown', this.keyDownListener)
      document.removeEventListener('keyup', this.keyUpListener)
    }
    this.keyDownListener = undefined
    this.keyUpListener = undefined
  }
}
